#!/usr/bin/env bash
# Reviewed: docs/specs/2026-10-11-p0-foundation.md (ADR-0002); assignments only, no secrets.
# Flutter app gates run in apps/mobile; each command runs in its own bash -c from the repo root.
export gate_tools='bash git python3 jq flutter sha256sum mkdir'
export format='cd apps/mobile && dart format lib test tool'
export lint='python3 scripts/check-adoption.py --lint && cd apps/mobile && dart format --output=none --set-exit-if-changed lib test tool'
export typecheck='cd apps/mobile && flutter analyze --fatal-infos'
export test='python3 scripts/check-adoption.py && python3 scripts/check-release-manifest.py --self-test && bash scripts/test-hooks-gate.sh && bash scripts/test-hooks-gate-guard.sh && bash scripts/test-dev-task-gate-lock.sh && bash scripts/check-xt-yaml-sync.sh && python3 .xtemplates/scripts/xt.py progress-check PROGRESS.md && python3 scripts/test-repo-checks.py && bash scripts/check-repo-tree.sh && python3 scripts/check-links.py && python3 scripts/check-architecture.py && python3 scripts/check-test-assertions.py && python3 scripts/check-licenses.py && cd apps/mobile && TZ=UTC LANG=C.UTF-8 LC_ALL=C.UTF-8 flutter test --branch-coverage && python3 ../../scripts/check-coverage.py --lcov coverage/lcov.info --baseline coverage-baseline.json && (cd android && ./gradlew -q :app:testDebugUnitTest --rerun)'
# build also merges the release manifest (~2-3 s) and fails on new permissions/exported components (F-008);
# the old merged manifest is removed first so a moved output path fails instead of passing on a stale file.
export build='rm -f apps/mobile/build/app/intermediates/merged_manifest/release/processReleaseMainManifest/AndroidManifest.xml && (cd apps/mobile && flutter pub get --enforce-lockfile && flutter build apk --debug && cd android && ./gradlew -q :app:processReleaseMainManifest) && python3 scripts/check-release-manifest.py apps/mobile/build/app/intermediates/merged_manifest/release/processReleaseMainManifest/AndroidManifest.xml && python3 scripts/check-apk-size.py --apk apps/mobile/build/app/outputs/flutter-apk/app-debug.apk --budget apps/mobile/apk-size-budget.json && python3 scripts/check-16kb-pages.py --apk apps/mobile/build/app/outputs/flutter-apk/app-debug.apk'
